def symmetries(T):
    out=[]
    cur=set(T)
    for rot in range(4):
        for flip in [False,True]:
            pts={(r, -c if flip else c) for r,c in cur}
            rmin=min(r for r,c in pts); cmin=min(c for r,c in pts)
            out.append({(r-rmin,c-cmin) for r,c in pts})
        cur={(c,-r) for r,c in cur}
    # unique
    u=[]
    for x in out:
        if x not in u:u.append(x)
    return u
